    --link-hover-color: var(--fa-blue);
    --table-background: var(--gray-50);
    --table-th-background: var(--gray-100);
    --table-row-background: var(--gray-50);
    --table-striped-row-background: var(--gray-100);
    --table-cell-border-color: var(--gray-300);
